insert into uat_steps (id, seq, area, title, instructions, expect, closes, expect_fail, fields, active, updated_at) values
  ('S1', 1, 'Setup', 'Install the gateway', 'Run vantage-gateway-<version>.msi on the gateway machine as an administrator. Leave the last screen''s box ticked for S2.', 'It installs without asking for Java. Services shows Vantage Sync Gateway. Start menu has Vantage > Configure Vantage Sync Gateway.', null, null, '[{"key":"version","label":"MSI version"},{"key":"machine","label":"Machine"},{"key":"service","label":"Service present? (yes/no)"},{"key":"shortcut","label":"Start-menu entry present? (yes/no)"}]'::jsonb, true, now()),
  ('S2', 2, 'Setup', 'Give the gateway its application.yml', 'On the installer''s last screen press Finish with the box ticked (or use the Start-menu entry). Pick the prepared application.yml and approve the administrator prompt.', 'The file is copied to C:\ProgramData\Vantage\gateway, the service restarts, and a message says /health answered.', null, null, '[{"key":"message","label":"Message shown"},{"key":"port","label":"Port"},{"key":"backup","label":"Previous file kept as .bak? (yes/no/n.a.)"}]'::jsonb, true, now()),
  ('S3', 3, 'Setup', 'The gateway refuses the wrong file', 'Run Configure Vantage Sync Gateway again and pick a till''s lane.properties, then a copy of application.yml.example.', 'Both are refused by name and nothing changes: the first has no bc:/gateway: sections, the second has the placeholder key.', null, null, '[{"key":"lane_msg","label":"Message for lane.properties"},{"key":"example_msg","label":"Message for the example file"}]'::jsonb, true, now()),
  ('S4', 4, 'Setup', 'The gateway reaches Business Central', 'In PowerShell: Invoke-RestMethod http://localhost:<port>/api/bc/handshake -Headers @{ ''X-Gateway-Api-Key'' = ''<key>'' }', 'The company list comes back and includes ZimChoice Supermarkets.', null, null, '[{"key":"companies","label":"Companies returned"}]'::jsonb, true, now()),
  ('S5', 5, 'Setup', 'ZWG as a POS currency', 'Business Central: Currencies > ZWG > Vantage POS: POS Currency, Lowest Denomination. Currency Exchange Rates: a ZWG rate starting today.', 'POS Currency ticked, Lowest Denomination 0.10, a rate dated today.', 'VPOS-86, VPOS-81', null, '[{"key":"pos_currency","label":"POS Currency"},{"key":"lowest","label":"Lowest Denomination"},{"key":"rate","label":"Rate and starting date"}]'::jsonb, true, now()),
  ('S6', 6, 'Setup', 'VAT posting and ZIMRA tax mappings', 'VAT Posting Setup: the rows for the store''s group (LOCAL) and each item VAT group. Vantage Tax Code Mappings: the LOCAL rows.', 'LOCAL x STD155 is 15.5% and maps to tax id 517. Every VAT group the catalogue uses has a mapping. The letter E is used only for exempt.', 'G7 (VPOS-96)', null, '[{"key":"std155","label":"STD155: VAT % / tax id / letter"},{"key":"zero","label":"ZERO: VAT % / tax id / letter"},{"key":"exempt","label":"EXEMPT: VAT % / tax id / letter"},{"key":"notax","label":"NO TAX: VAT % / tax id / letter"}]'::jsonb, true, now()),
  ('S7', 7, 'Setup', 'Tender types', 'Vantage Tender Types: CASH_USD, CASH_ZWG, the card tender and CUSTOMER. For each: Account No., Overtender Allowed, Change Tender Code, Rounding To, Drawer Opens. CASH_ZWG also: Currency Code ZWG, Foreign Currency ticked, Seek Authorization None.', 'Every tender has an account. Both cash tenders allow overtender (or change can never be given). CASH_ZWG is ZWG drawer cash.', 'VPOS-79, VPOS-80', null, '[{"key":"cash_usd","label":"CASH_USD: account / overtender / rounding"},{"key":"cash_zwg","label":"CASH_ZWG: account / overtender / currency / seek auth."},{"key":"card","label":"Card tender: account / seek auth."},{"key":"customer","label":"CUSTOMER: account"}]'::jsonb, true, now()),
  ('S8', 8, 'Setup', 'Functionality profile', 'Vantage POS Func. Profiles > DEFAULT (or the store''s): Prices Include VAT, Staff PIN Logon, Customer Account Enabled, Dual Pricing Enabled and Secondary Currency Code, Max Drawer Hours, Live Stock Posting, Must Key Price if Zero, Max. Quantity, Max. Price.', 'Values match what the supermarket day needs. Record what you set, including anything left off.', null, null, '[{"key":"incl_vat","label":"Prices Include VAT"},{"key":"account","label":"Customer Account Enabled"},{"key":"dual","label":"Dual Pricing Enabled / Secondary Currency"},{"key":"drawer_hours","label":"Max Drawer Hours"},{"key":"live_stock","label":"Live Stock Posting"},{"key":"key_zero","label":"Must Key Price if Zero"}]'::jsonb, true, now()),
  ('S9', 9, 'Setup', 'Hardware profile', 'Vantage POS HW Profiles > the store''s profile: Receipt Printer Type and Address, Receipt Width, Cash Drawer Port, Open Drawer on Sale, Scale Enabled and Port, EFT Endpoint URL, FDMS Endpoint URL.', 'Open Drawer on Sale ticked. Endpoints filled for what this store uses. No device keys here - they live in each till''s lane.properties.', null, null, '[{"key":"printer","label":"Printer type / address / width"},{"key":"drawer","label":"Drawer port / Open Drawer on Sale"},{"key":"scale","label":"Scale enabled / port"},{"key":"eft","label":"EFT endpoint"},{"key":"fdms","label":"FDMS endpoint"}]'::jsonb, true, now()),
  ('S10', 10, 'Setup', 'The store', 'Vantage Stores > 5001: Location Code, Currency Code (blank = LCY), Func./Hardware/Menu Profile Code, VAT Bus. Posting Group, VAT Registration No., TIN No., Store Dimension Value.', 'VAT Bus. Posting Group is LOCAL (blank sells everything at 0%). TIN and VAT number filled so they print on the slip.', null, 'G20 (VPOS-109): TIN and VAT no. were blank on 24 Sep', '[{"key":"location","label":"Location Code"},{"key":"vat_group","label":"VAT Bus. Posting Group"},{"key":"tin","label":"TIN No."},{"key":"vat_no","label":"VAT Registration No."},{"key":"profiles","label":"Func. / HW / Menu profile"}]'::jsonb, true, now()),
  ('S11', 11, 'Setup', 'A terminal for every tester''s till', 'Store card 5001 > POS Terminals: one line per till. Terminal Type Till; leave the profile codes blank to inherit the store''s; Auto Logoff After (Min.).', 'One terminal per tester''s till, each a distinct number.', null, null, '[{"key":"terminals","label":"Terminal numbers and who uses each"}]'::jsonb, true, now()),
  ('S12', 12, 'Setup', 'Staff permission groups', 'Vantage Staff Perm. Groups: a cashier group and a manager group. Manager: Manager Privileges, Void Line/Transaction, Refund/Return, Price Override, Max. Line and Total Discount %.', 'A cashier group without Manager Privileges and a manager group with it.', 'VPOS-65', null, '[{"key":"cashier","label":"Cashier group: code / max line disc. %"},{"key":"manager","label":"Manager group: code / max line disc. %"}]'::jsonb, true, now()),
  ('S13', 13, 'Setup', 'Staff and PINs', 'Vantage Staff: a record for every tester (Store No. 5001, a group), then Set PIN on each. Then try to give a second person a PIN already in use.', 'Every tester has a PIN. The duplicate is refused, naming who holds it.', 'VPOS-66', null, '[{"key":"staff","label":"Staff IDs created"},{"key":"duplicate","label":"Message for the duplicate PIN"}]'::jsonb, true, now()),
  ('S14', 14, 'Setup', 'Cash movement reasons', 'Vantage Cash Movement Reasons: at least two payout reasons, each with a G/L Account No.', 'Reasons with an account. The till offers only these for a payout.', 'VPOS-33', null, '[{"key":"reasons","label":"Reason codes and G/L accounts"}]'::jsonb, true, now()),
  ('S15', 15, 'Setup', 'Quick keys', 'Vantage POS Menu Profiles > the store''s profile: pages and buttons, including a No Sale and a Reprint function key if the store wants them. Set it on the store card.', 'The F7 grid on the till shows the buttons. Without buttons, No Sale and Reprint of the last receipt are unreachable except from the post-sale screen.', null, null, '[{"key":"profile","label":"Menu profile"},{"key":"buttons","label":"Buttons added"}]'::jsonb, true, now()),
  ('S16', 16, 'Setup', 'Scales and embedded barcodes (if scales are used)', 'Vantage Embedded Barcodes: the store''s label rule. Open Vantage Embedded Barcode Test and decode a real label. Tick Vantage Scale Item on the weighed items.', 'The test page decodes the label to the right item, weight or price. Skip with ''Not run'' if the store has no scales.', 'VPOS-36', null, '[{"key":"rule","label":"Rule code / prefix / length"},{"key":"test_label","label":"Label tested and what it decoded to"},{"key":"scale_items","label":"Items flagged as scale items"}]'::jsonb, true, now()),
  ('S17', 17, 'Setup', 'Posting setup', 'Vantage POS Posting Setup: journal template and batch, Item journal template and batch, Statement Nos. (with room on its No. Series), Rounding Account No., Cash Difference Acc., Max. Rounding Amount, Max. Cash Difference, Local Currency Code, Store Dimension Code, Safe Account No.', 'All filled. Max. Rounding Amount small, so a wrong tender cannot hide in the Rounding Account.', 'VPOS-35', null, '[{"key":"statement_nos","label":"Statement Nos. / last used / ending"},{"key":"rounding","label":"Rounding Account / Max. Rounding Amount"},{"key":"cash_diff","label":"Cash Difference Acc. / Max. Cash Difference"},{"key":"lcy","label":"Local Currency Code"}]'::jsonb, true, now()),
  ('S18', 18, 'Setup', 'Account customers and live stock', 'Customers for the on-account steps: not blocked, with a credit limit. If Live Stock Posting is on: a Job Queue Entry for codeunit 50802 (Vantage Live Stock Job). Inventory Setup: Prevent Negative Inventory.', 'At least one account customer with a limit. The job queue entry runs 50802, not 50800 (50800 logs Success and posts nothing), and is Ready (or Live Stock Posting is off).', 'VPOS-27, VPOS-32', null, '[{"key":"customer","label":"Customer no. / credit limit"},{"key":"jobq","label":"Job queue entry (yes/no/n.a.)"},{"key":"neg_inv","label":"Prevent Negative Inventory"}]'::jsonb, true, now()),
  ('S19', 19, 'Setup', 'Install the till', 'Run the till MSI on the tester''s machine. Start Vantage from the Start menu or desktop shortcut (not from a repo folder).', 'It installs and starts. With no settings file yet, it asks for this till''s lane.properties.', null, null, '[{"key":"version","label":"Till version (F9, bottom right)"},{"key":"machine","label":"Machine"},{"key":"asked","label":"Asked for lane.properties? (yes/no)"}]'::jsonb, true, now()),
  ('S20', 20, 'Setup', 'Give the till its lane.properties', 'Answer Yes and pick this till''s lane.properties (store 5001, its terminal, gateway URL and key, FDMS device id and key).', 'It says where it copied the file (.vantage) and the till opens as 5001/<terminal> in the title bar, with no restart.', null, null, '[{"key":"copied_to","label":"Where it was copied"},{"key":"title","label":"Title bar"}]'::jsonb, true, now()),
  ('S21', 21, 'Setup', 'The till refuses the wrong file', 'On a till with no settings (or from Lane setup > Load from a lane.properties file), pick the gateway''s application.yml.', 'Refused by name: it names no gateway and no store. Nothing is written.', null, null, '[{"key":"message","label":"Message shown"}]'::jsonb, true, now()),
  ('S22', 22, 'Setup', 'Lane setup and the logo', 'Sign-in screen > Lane setup > setup code or a manager PIN. Check the values, set Receipt logo and Screen logo to the store''s PNG, Save.', 'It saves (the file path is shown). The header and the basket watermark change to the store''s logo straight away, not TV Sales & Home''s.', 'VPOS-118', null, '[{"key":"saved_to","label":"Saved to"},{"key":"logo","label":"Logo shown after saving"}]'::jsonb, true, now()),
  ('S23', 23, 'Setup', 'First sync', 'Open F9 Status · Sync and wait for the channels to settle.', 'All synced, with the catalogue, prices, staff, tenders and currencies down and nothing failed. Signing in shows every tester''s name.', 'VPOS-85', null, '[{"key":"status","label":"Status headline"},{"key":"channels","label":"Any channel not green"},{"key":"staff","label":"Staff shown on sign-in"}]'::jsonb, true, now()),
  ('S24', 24, 'Setup', 'Printer and drawer', 'F9 > Printers on this till: pick the receipt printer, Print test slip, then Open drawer.', 'The slip prints with the store''s logo and the drawer opens.', null, null, '[{"key":"printer","label":"Printer chosen"},{"key":"slip","label":"Test slip printed? (yes/no)"},{"key":"drawer","label":"Drawer opened? (yes/no)"}]'::jsonb, true, now()),
  ('S25', 25, 'Setup', 'Fiscal device and card terminal ready', 'F9: read the ZIMRA and card lines. Confirm in the FDMS portal that this till''s device has an open fiscal day, and that PayBridge is running for tills with a card terminal.', 'ZIMRA configured with this till''s device id; fiscal day open. Card link up where a terminal is fitted.', 'VPOS-31', null, '[{"key":"device","label":"FDMS device id"},{"key":"day","label":"Fiscal day no. open"},{"key":"card","label":"Card link status"}]'::jsonb, true, now()),
  ('C1', 26, 'Setup, exercised', 'Create a store from nothing', 'Vantage Stores, New: store UAT2 with Name, Address, City, Phone, Store Type, Location Code, Store Dimension Value, Currency Code, VAT Bus. Posting Group, Func. Profile, Hardware Profile, TIN No., VAT Registration No. Under it (Store Terminals) add one terminal with no profiles of its own. On a spare till (or yours, then put it back), Lane setup: choose UAT2 and its terminal, save, F9 Status · Sync on the till, sign in and sell one item.', 'Lane setup lists UAT2 and its terminal. The receipt header prints UAT2''s name, address, phone, TIN and VAT no. The sale lands in BC under store UAT2 and that terminal.', null, null, '[{"key":"store","label":"Store no. / terminal no."},{"key":"header","label":"Receipt header as printed"},{"key":"bc","label":"Transaction no. in BC"}]'::jsonb, true, now()),
  ('C2', 27, 'Setup, exercised', 'The store''s location and VAT group reach posting', 'Post the UAT2 sale (live stock or the statement). Look at its Item Ledger Entry and its VAT Entry. Then blank UAT2''s Location Code, sell again, post, and look again.', 'With a Location Code: the stock leaves UAT2''s location. Blank: it leaves Vantage POS Posting Setup''s Default Location Code. The VAT entry carries UAT2''s VAT Bus. Posting Group (the setup''s Default VAT Bus. Posting Group only when the store has none).', null, null, '[{"key":"loc_set","label":"Location on the ledger (store location set)"},{"key":"loc_blank","label":"Location on the ledger (store location blank)"},{"key":"vat_bus","label":"VAT Bus. Posting Group on the VAT entry"}]'::jsonb, true, now()),
  ('C3', 28, 'Setup, exercised', 'The store dimension', 'Vantage POS Posting Setup: Store Dimension Code set. Blank UAT2''s Store Dimension Value and calculate, then post, a statement for UAT2. Then fill it and post again.', 'Blank: the statement refuses, naming store UAT2 and the dimension. Filled: every revenue, VAT, tender and stock G/L entry of UAT2 carries that dimension value, and store 5001''s entries carry 5001''s.', null, null, '[{"key":"refusal","label":"Refusal text"},{"key":"dim","label":"Dimension value on the G/L entries"}]'::jsonb, true, now()),
  ('C4', 29, 'Setup, exercised', 'A blocked terminal and a blocked store', 'Tick Blocked on UAT2''s terminal, F9 Status · Sync on the till, try to sell. Untick it, tick Blocked on store UAT2, sync, try again. Untick it.', 'Each time the till refuses to sell and says the terminal (or store) is blocked in Business Central.', null, 'Read in the code, not yet run: the till syncs and stores this setting but nothing reads it (Blocked on the store and on the terminal): the till keeps selling', '[{"key":"terminal","label":"Blocked terminal: what the till did"},{"key":"store","label":"Blocked store: what the till did"}]'::jsonb, true, now()),
  ('C5', 30, 'Setup, exercised', 'A terminal''s own profile beats the store''s', 'Copy the store''s functionality profile to UAT-ALT and change one thing the till reads: untick Customer Account Enabled. Put UAT-ALT on one terminal only (Func. Profile Code on the terminal card). F9 Status · Sync on the till on that till and on a till still on the store''s profile. On each, look for F2 Customer, then attach an account customer and try to pay on account.', 'The UAT-ALT till has no F2 Customer key (unless Hire-to-Buy or Lay-By is on in UAT-ALT) and offers no on-account tender; the other till works as in T21. Put the terminal''s profile back afterwards.', null, null, '[{"key":"alt","label":"Till on UAT-ALT: F2 shown? on-account offered?"},{"key":"store","label":"Till on the store''s profile: same"}]'::jsonb, true, now()),
  ('C6', 31, 'Setup, exercised', 'Max Drawer Hours', 'On UAT-ALT set Max Drawer Hours = 1 and sync. Open a shift and sell. Come back more than an hour later and sell again.', 'After the hour the till refuses the sale, says the drawer is stale, and F11 then 6 End of day still works so the Z can be cut. With 0 there is no limit.', null, null, '[{"key":"opened","label":"Shift opened at"},{"key":"refused","label":"Refused at / message"},{"key":"z","label":"Z cut? (yes/no)"}]'::jsonb, true, now()),
  ('C7', 32, 'Setup, exercised', 'Dual pricing on and off', 'On UAT-ALT untick Dual Pricing Enabled, sync, ring an item. Tick it with Secondary Currency Code ZWG, sync, ring it again.', 'Off: no F1 key and no second-currency figures on screen or receipt. On: F1 prices the sale in ZWG and the receipt shows the ZWG total.', null, null, '[{"key":"off","label":"Dual pricing off: what showed"},{"key":"on","label":"Dual pricing on: what showed"}]'::jsonb, true, now()),
  ('C8', 33, 'Setup, exercised', 'Amount rounding', 'On a tender and currency with no rounding of their own, set the profile''s Amount Rounding Method Nearest and Amount Rounding To 0.05. Sync. Ring a basket ending in .03 and pay it with that tender.', 'The amount due rounds to .05 and the rounding shows on the receipt. Record the tender used.', null, null, '[{"key":"tender","label":"Tender used"},{"key":"basket","label":"Basket total"},{"key":"due","label":"Amount due / rounding"}]'::jsonb, true, now()),
  ('C9', 34, 'Setup, exercised', 'Max. Quantity and Max. Price', 'On UAT-ALT set Max. Quantity 50 and Max. Price 500.00. Sync. Key a quantity of 99 on a line; open a price override and key 900.00.', 'Both refused, with the limit named.', null, 'Read in the code, not yet run: the till syncs and stores this setting but nothing reads it: 99 and 900.00 are both taken', '[{"key":"qty","label":"What quantity 99 did"},{"key":"price","label":"What price 900.00 did"}]'::jsonb, true, now()),
  ('C10', 35, 'Setup, exercised', 'Staff PIN Logon and Staff Barcode Logon', 'On UAT-ALT untick Staff PIN Logon and tick Staff Barcode Logon. Sync. Sign out and sign in.', 'The sign-in asks for a staff barcode, not a PIN.', null, 'Read in the code, not yet run: the till syncs and stores this setting but nothing reads it: the sign-in asks for a PIN either way', '[{"key":"signin","label":"What the sign-in asked for"}]'::jsonb, true, now()),
  ('C11', 36, 'Setup, exercised', 'Prices Include VAT and Show VAT on Receipt', 'Note an item''s BC Unit Price and what the till charges (T4). On UAT-ALT untick Prices Include VAT and Show VAT on Receipt. Sync, ring the item again.', 'The till now adds VAT on top of the Unit Price, and the receipt has no VAT section. Tick both back afterwards.', null, 'Read in the code, not yet run: the till syncs and stores this setting but nothing reads it (both settings, and Currency Symbol and Price Rounding): the price and the receipt do not change', '[{"key":"before","label":"Charged before"},{"key":"after","label":"Charged after"},{"key":"vat_line","label":"VAT section on the receipt after? (yes/no)"}]'::jsonb, true, now()),
  ('C12', 37, 'Setup, exercised', 'Every item''s posting groups resolve', 'List the Gen. Prod. Posting Groups on the ZimChoice items. In General Posting Setup check two rows for each: blank Gen. Bus. + the group (Inventory Adjmt. Account), and Vantage POS Posting Setup''s Default Gen. Bus. Post. Group + the group (Sales Account, COGS Account, Inventory Adjmt. Account). Check every item has a VAT Prod. Posting Group. Then Adjust Inventory one item of each group, and sell and post one of each.', 'No missing row. Adjust Inventory works (a missing blank + group row gives ''The General Posting Setup does not exist'', as on item 4096 on 24 Sep). The sales post revenue and COGS under the default business group.', null, null, '[{"key":"groups","label":"Gen. Prod. groups used"},{"key":"missing","label":"Rows that were missing"},{"key":"no_vat","label":"Items with no VAT Prod. group"}]'::jsonb, true, now()),
  ('C13', 38, 'Setup, exercised', 'Live stock posting', 'Job queue entry: Object ID to Run 50802 (Vantage Live Stock Job), 1 minute between runs, Ready. Live Stock Posting on in the profile. Sell an item with stock; wait 2 minutes; open its Item Ledger Entries. Then sell an item whose posting fails (for example one with no General Posting Setup row, or no stock with Prevent Negative Inventory on).', 'The good sale is on the item ledger within about two minutes, before any statement. The bad one shows on Vantage Live Stock Worklist with its error while the job log still says Success; once fixed it posts on the next run (or with the statement). An entry on 50800 logs Success and posts nothing.', null, null, '[{"key":"minutes","label":"Minutes from sale to ledger"},{"key":"worklist","label":"Worklist error for the bad line"},{"key":"after_fix","label":"Posted after the fix? (yes/no)"}]'::jsonb, true, now()),
  ('C14', 39, 'Setup, exercised', 'Statement numbers, journals and source code', 'After B5, open the posted statement and its G/L entries.', 'The statement number comes from Statement Nos.; the G/L entries'' document no. from Posting Nos. (when set); Source Code as set; posted through the Gen. Journal template and batch from the setup. Cash takings post to the cash tender''s own Account No. (the setup''s Cash Account No. is not used by posting).', null, null, '[{"key":"statement","label":"Statement no."},{"key":"doc","label":"G/L document no."},{"key":"source","label":"Source code on the entries"}]'::jsonb, true, now()),
  ('C15', 40, 'Setup, exercised', 'Cash movements post to their accounts', 'Post a statement for a day with a pickup, a safe drop, a float add and a payout (T24). Then blank Safe Account No., calculate a statement with a safe drop and post it; do the same with Cash in Transit Acc. and a pickup. Put both back.', 'Pickup to Cash in Transit Acc., safe drop to Safe Account No., payout to its reason''s G/L account. With an account blank, posting refuses and names the missing account and the movement.', null, null, '[{"key":"accounts","label":"Account hit by each movement"},{"key":"safe_refusal","label":"Refusal with Safe Account blank"},{"key":"transit_refusal","label":"Refusal with Cash in Transit blank"}]'::jsonb, true, now()),
  ('C16', 41, 'Setup, exercised', 'Cash difference over the limit', 'Set Max. Cash Difference 1.00. Declare a drawer 5.00 short at the Z. Post the statement; then, on the statement''s Cash Drawers, Accept Cash Difference and post again.', 'The first post refuses, naming the terminal, the difference and the limit. After acceptance it posts: the 5.00 to Cash Difference Acc. against the cash tender account.', null, null, '[{"key":"refusal","label":"Refusal text"},{"key":"posted","label":"Cash Difference Acc. amount"}]'::jsonb, true, now()),
  ('T1', 42, 'Till', 'Sign on and count the float', 'Sign in as a cashier and count the float for each cash currency the till asks for.', 'The till asks for USD and ZWG, and opens a shift.', 'VPOS-33', 'G4 (VPOS-93): asks for ZWG only', '[{"key":"shift","label":"Shift no."},{"key":"asked","label":"Currencies asked for"},{"key":"usd_float","label":"USD float"},{"key":"zwg_float","label":"ZWG float"}]'::jsonb, true, now()),
  ('T2', 43, 'Till', 'Reopen without a Z', 'Close the app and reopen it without cutting a Z.', 'The same shift resumes with the float you counted, not a fresh prompt.', 'VPOS-33', null, '[{"key":"shift","label":"Shift no. after reopening"},{"key":"float","label":"Float shown"}]'::jsonb, true, now()),
  ('T3', 44, 'Till', 'A manager''s own PIN at a supervisor gate', 'As the cashier, trigger a supervisor gate (a line discount over 10%, or End of day). Enter the manager''s PIN.', 'Accepted, and the approval names the manager.', 'VPOS-65', null, '[{"key":"gate","label":"Gate used"},{"key":"approver","label":"Approver shown"}]'::jsonb, true, now()),
  ('T4', 45, 'Till', 'Till price matches the shelf', 'Scan the two items with a known shelf price (note the shelf price and the BC Unit Price first).', 'The till charges exactly the shelf price.', 'U1 (VPOS-112)', null, '[{"key":"item1","label":"Item 1 no."},{"key":"item1_shelf","label":"Item 1 shelf price"},{"key":"item1_till","label":"Item 1 till price (incl. VAT)"},{"key":"item2","label":"Item 2 no."},{"key":"item2_shelf","label":"Item 2 shelf price"},{"key":"item2_till","label":"Item 2 till price (incl. VAT)"}]'::jsonb, true, now()),
  ('T5', 46, 'Till', 'Key an item number; find one by name', 'Key an item number with no barcode. Then press F3 and find an item by part of its name.', 'Both ring.', null, null, '[{"key":"keyed","label":"Item keyed"},{"key":"searched","label":"Item found with F3"}]'::jsonb, true, now()),
  ('T6', 47, 'Till', 'VAT and band per kind of item', 'Ring one standard-rated, one zero-rated, one exempt and one blank-VAT-group item. Look each up in BC''s VAT Posting Setup. After tendering, read the bands on the fiscal slip.', 'Each line''s VAT % equals BC''s setup for that item, and the slip declares the right band.', 'G7 (VPOS-96)', null, '[{"key":"std","label":"Standard: item, BC %, till %, band on slip"},{"key":"zero","label":"Zero-rated: item, BC %, till %, band"},{"key":"exempt","label":"Exempt: item, BC %, till %, band"},{"key":"blank","label":"Blank group: item, BC %, till %, band"}]'::jsonb, true, now()),
  ('T7', 48, 'Till', 'A zero-priced item', 'Ring an item whose price in BC is 0.', 'The till asks for a price or refuses it.', null, 'G11 (VPOS-100): rings at 0.00', '[{"key":"item","label":"Item no."},{"key":"what","label":"What happened"}]'::jsonb, true, now()),
  ('T8', 49, 'Till', 'Void a line, then a whole sale', 'Void one line of a sale and finish it. Then ring another sale and void it whole (F11 → 5).', 'Both voids are recorded and reach BC (check in B1).', null, 'G8 (VPOS-97): a voided sale leaves no record', '[{"key":"line_void_receipt","label":"Receipt with the voided line"},{"key":"void_receipt","label":"Receipt no. of the voided sale"}]'::jsonb, true, now()),
  ('T9', 50, 'Till', 'Park and recall', 'Park a basket (F8), ring and finish another sale, then recall the parked one and finish it.', 'The parked basket comes back whole.', null, null, '[{"key":"parked","label":"Parked receipt no."},{"key":"recalled_total","label":"Total after recall"}]'::jsonb, true, now()),
  ('T10', 51, 'Till', 'Sign out mid-basket', 'A manager rings two items and signs out without finishing. A cashier signs in.', 'The cashier gets a fresh basket under their own name, without the manager''s rights.', null, 'G10 (VPOS-99): keeps the basket and the previous person''s rights', '[{"key":"staff_on_receipt","label":"Staff on the next receipt"},{"key":"basket","label":"What the cashier saw"}]'::jsonb, true, now()),
  ('T11', 52, 'Till', 'Line discount at 10%, then 15%', 'As a cashier, give 10% on a line, then 15% on another.', '10% is taken; 15% asks for a supervisor.', null, null, '[{"key":"ten","label":"Line amount after 10%"},{"key":"fifteen","label":"What 15% did"}]'::jsonb, true, now()),
  ('T12', 53, 'Till', 'USD cash, exact', 'Ring a sale and tender exact USD cash.', 'The sale closes and the drawer opens.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"drawer","label":"Drawer opened? (yes/no)"}]'::jsonb, true, now()),
  ('T13', 54, 'Till', 'USD cash with change', 'Ring a sale and hand over more than the total in USD.', 'Change is shown and paid = gross + rounding + change.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"paid","label":"Paid"},{"key":"rounding","label":"Rounding"},{"key":"change","label":"Change"}]'::jsonb, true, now()),
  ('T14', 55, 'Till', 'Settle a USD sale in ZWG notes', 'Open tendering on a USD sale. Before pressing, read the Cash ZWG key. Then settle it entirely in ZWG.', 'The key shows the rate and the ZWG balance. The sale closes and the receipt names the tender by its description.', 'VPOS-79, VPOS-80, VPOS-82, VPOS-83', null, '[{"key":"receipt","label":"Receipt no."},{"key":"rate","label":"Rate on the key"},{"key":"usd","label":"USD gross"},{"key":"zwg","label":"ZWG paid"},{"key":"tender_name","label":"Tender name on the receipt"}]'::jsonb, true, now()),
  ('T15', 56, 'Till', 'An unpayable ZWG amount', 'Key a ZWG amount that is not a multiple of 0.10.', 'Refused, naming the denomination.', 'VPOS-81', null, '[{"key":"keyed","label":"Amount keyed"},{"key":"message","label":"Message shown"}]'::jsonb, true, now()),
  ('T16', 57, 'Till', 'Change from the ZWG drawer', 'Overtender a sale in ZWG notes.', 'Change comes back in ZWG, rounded to 0.10, and paid = gross + rounding + change.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"zwg_paid","label":"ZWG paid"},{"key":"change","label":"Change"},{"key":"rounding","label":"Rounding"}]'::jsonb, true, now()),
  ('T17', 58, 'Till', 'Split USD cash and ZWG notes', 'Settle one sale partly in USD cash and partly in ZWG notes.', 'The sale closes. The fiscal receipt is in the sale''s currency.', null, 'G13 (VPOS-102): fiscalises in ZWG', '[{"key":"receipt","label":"Receipt no."},{"key":"usd_leg","label":"USD leg"},{"key":"zwg_leg","label":"ZWG leg"},{"key":"fiscal_currency","label":"Currency on the fiscal receipt"}]'::jsonb, true, now()),
  ('T18', 59, 'Till', 'Card for an odd total', 'Ring a basket whose total is not a coin multiple and pay by card.', 'The card is charged the exact gross.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"charged","label":"Amount on the card slip"}]'::jsonb, true, now()),
  ('T19', 60, 'Till', 'A card decline', 'Force a decline (wrong PIN).', 'The till offers another tender and takes nothing. Do not retry a decline.', null, null, '[{"key":"response","label":"What the till showed"}]'::jsonb, true, now()),
  ('T20', 61, 'Till', 'EcoCash through the terminal', 'Take an EcoCash payment through the card terminal.', 'Declared to ZIMRA as MobileWallet, not Card (read the fiscal record or ask Wyne to).', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"money_type","label":"Money type declared"}]'::jsonb, true, now()),
  ('T21', 62, 'Till', 'A customer on account', 'F2, attach an account customer, tender on account inside the limit. Then try an amount over the limit.', 'Accepted inside the limit; refused over it with the reason.', 'VPOS-27, VPOS-56', null, '[{"key":"customer","label":"Customer no."},{"key":"receipt","label":"Receipt no."},{"key":"amount","label":"Amount"},{"key":"refusal","label":"Refusal text over the limit"}]'::jsonb, true, now()),
  ('T22', 63, 'Till', 'The fiscal slip, online and offline', 'Read a printed slip and scan its QR with a phone. Then pull the network, make one sale, and plug it back in.', 'Fiscal block, QR that verifies, VAT by band. Offline, the slip says fiscalisation is pending and the stamps arrive once the network is back.', 'VPOS-31', null, '[{"key":"day","label":"Fiscal day"},{"key":"global","label":"Global no."},{"key":"code","label":"Verification code"},{"key":"qr","label":"QR verified? (yes/no)"},{"key":"offline_receipt","label":"Offline receipt no."},{"key":"offline_stamped","label":"Stamped after reconnecting? (yes/no)"}]'::jsonb, true, now()),
  ('T23', 64, 'Till', 'Returns', 'Refund a whole receipt. Return 2 of 6 on a line, then the rest. Return a receipt from another till. Try to refund a sale that has not been fiscalised yet.', 'Credit notes of 20 characters or fewer, summing to the original to the cent. The last one is refused.', 'VPOS-57, VPOS-39', 'G12 (VPOS-101): an unfiscalised sale is not refused', '[{"key":"whole","label":"Whole return: CN no., amount"},{"key":"partials","label":"Partials: CN nos., amounts"},{"key":"other_till","label":"Other till: CN no."},{"key":"unfiscalised","label":"Unfiscalised refund: what happened"}]'::jsonb, true, now()),
  ('T24', 65, 'Till', 'Pickup, safe drop, float add, payout', 'Manager menu → 7 with an empty basket. Do one of each, including a payout with reason Other.', 'A slip each, and the drawer''s expected cash moves by exactly that amount.', 'VPOS-33, VPOS-73', null, '[{"key":"pickup","label":"Pickup amount"},{"key":"drop","label":"Safe drop amount"},{"key":"float_add","label":"Float add amount"},{"key":"payout","label":"Payout amount and reason"}]'::jsonb, true, now()),
  ('T25', 66, 'Till', 'A basket across a Z', 'Open a basket on one till. Cut the Z, open a new shift, then tender the basket.', 'The sale lands on the shift it was tendered on.', 'VPOS-64', null, '[{"key":"receipt","label":"Receipt no."},{"key":"shift","label":"Shift it landed on"}]'::jsonb, true, now()),
  ('T26', 67, 'Till', 'Declare and cut the Z', 'End of day: count each cash drawer and declare, then cut the Z. Compare the screen with the paper.', 'A USD and a ZWG drawer, each with expected, counted and variance. Screen and paper agree.', 'VPOS-35, VPOS-68', 'G3 (VPOS-92): the USD drawer is not counted', '[{"key":"z","label":"Z / shift no."},{"key":"usd","label":"USD: expected / counted / variance"},{"key":"zwg","label":"ZWG: expected / counted / variance"},{"key":"gross","label":"Z gross"},{"key":"vat","label":"VAT by band"}]'::jsonb, true, now()),
  ('D1', 68, 'Discounts', 'Discount accounts', 'Vantage POS Posting Setup: tick Post Discounts to G/L and fill Line, Total, Periodic, Tender, Coupon, Manual and Customer Disc. Account with contra-revenue G/L accounts (one each, or shared, as finance wants).', 'Post Discounts to G/L on and every discount account filled. A blank account means that kind of discount is not posted on its own line: it disappears into revenue.', null, null, '[{"key":"post_gl","label":"Post Discounts to G/L (on/off)"},{"key":"accounts","label":"Line / Total / Periodic / Tender / Coupon / Manual / Customer accounts"}]'::jsonb, true, now()),
  ('D2', 69, 'Discounts', 'The first offer reaches the till', 'BC, Vantage Promotion Offers: new offer UAT-20PCT, type Disc. Offer, Status Enabled, Starting Date today, Ending Date blank, Currency Code blank. Promotion Lines: Scope Item, No. = an item with a known shelf price, Discount Percent 20. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Then ring that item once. If another tester has already made it, check it matches and use theirs.', 'Vantage Promotion RuleSets has a new version with the right Offer Count. The till takes 20% off with no restart; the receipt prints UAT-20PCT and the amount under the line, and a Promotions & discounts total. Note: the receipt prints the offer No., not its Description, so the No. is what customers read.', null, null, '[{"key":"version","label":"Rule set version / Offer Count"},{"key":"item","label":"Item no. / shelf price"},{"key":"charged","label":"Till charged"},{"key":"receipt","label":"Receipt no."}]'::jsonb, true, now()),
  ('D3', 70, 'Discounts', 'An offer price', 'Offer UAT-PRICE, Disc. Offer. Promotion Line: Scope Item, a second item, Offer Price = 1.00 below its shelf price. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring it.', 'The customer pays exactly the Offer Price as typed in BC, on the same basis as the shelf price (T4). Paying the offer price plus VAT is a fail: record both figures.', null, null, '[{"key":"item","label":"Item no. / shelf price"},{"key":"offer_price","label":"Offer Price in BC"},{"key":"charged","label":"Till charged"},{"key":"receipt","label":"Receipt no."}]'::jsonb, true, now()),
  ('D4', 71, 'Discounts', 'Multibuy tiers', 'Offer UAT-MULTI, type Multibuy, one item on its Promotion Lines. Multibuy Tiers: Min. Quantity 2, Discount Percent 10; Min. Quantity 3, Deal Unit Price = a price you choose. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring 1, then 2, then 3 of the item, each as its own sale.', '1: full price. 2: 10% off both. 3: every unit at the Deal Unit Price. Each discounted receipt prints UAT-MULTI.', null, null, '[{"key":"item","label":"Item no. / shelf price"},{"key":"one","label":"Total for 1"},{"key":"two","label":"Total for 2"},{"key":"three","label":"Total for 3"}]'::jsonb, true, now()),
  ('D5', 72, 'Discounts', 'Mix and match: three for two', 'Offer UAT-3FOR2, type Mix & Match, MixMatch Disc Type Least Expensive, No. of Lines to Trigger 3, No. of Least Expensive 1, Least Expensive Percent 100. Promotion Lines: three different items (Scope Item). Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring two of them; then all three; then six (two of each).', 'Two items: nothing off. Three: the cheapest is free. Six: the two cheapest are free.', null, null, '[{"key":"items","label":"Items and shelf prices"},{"key":"two","label":"Discount on 2 items"},{"key":"three","label":"Discount on 3 items"},{"key":"six","label":"Discount on 6 items"}]'::jsonb, true, now()),
  ('D6', 73, 'Discounts', 'A deal (bundle price)', 'Offer UAT-DEAL, type Deal, Deal Price = less than the two items'' shelf prices together. Promotion Lines: the two items (Scope Item). Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring one item alone; then both; then two of each.', 'One item: full price. Both: the pair costs the Deal Price. Two of each: both pairs at the Deal Price.', null, 'Read in the code, not yet run: a deal is applied once per sale, so the second pair is charged in full', '[{"key":"deal_price","label":"Deal Price in BC"},{"key":"one","label":"Total for 1 item"},{"key":"pair","label":"Total for the pair"},{"key":"two_pairs","label":"Total for two pairs"}]'::jsonb, true, now()),
  ('D7', 74, 'Discounts', 'Money off a big basket', 'Offer UAT-BASKET, type Total Discount, Discount Percent 5, Amount to Trigger 50.00, Maximum Discount Amount 5.00. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring a basket just under 50.00, then one just over, then one over 100.00.', 'Under 50: nothing. Over 50: 5% off the basket, spread across its lines. Over 100: 5.00 exactly (the cap).', null, null, '[{"key":"under","label":"Under 50: total / discount"},{"key":"over","label":"Over 50: total / discount"},{"key":"capped","label":"Over 100: total / discount"}]'::jsonb, true, now()),
  ('D8', 75, 'Discounts', 'A discount for paying by card', 'Offer UAT-CARD, type Tender Type, Tender Type Code = the card tender, Tender Offer Percent 2. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring the same basket twice: pay one by card, the other in cash. Run this after B5 has posted for the day (see D21).', 'Cash: no discount. Card: 2% off, shown before the card is charged; the terminal charges the discounted total; the fiscal slip total equals what the card paid.', null, null, '[{"key":"cash","label":"Cash sale total"},{"key":"due","label":"Card sale: amount due after the discount"},{"key":"charged","label":"Terminal charged"},{"key":"slip","label":"Fiscal slip total"}]'::jsonb, true, now()),
  ('D9', 76, 'Discounts', 'A customer''s discount group', 'Give the account customer from S18 a Customer Disc. Group. Offer UAT-CUST, type Line Discount, Customer Disc. Group = that group, Discount Percent 10, Promotion Line Scope All. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring an item with no customer; then F2, attach the customer, ring it again.', 'No customer: full price. With the customer: 10% off, receipt prints UAT-CUST.', null, null, '[{"key":"group","label":"Customer / Disc. Group"},{"key":"without","label":"Charged without the customer"},{"key":"with","label":"Charged with the customer"}]'::jsonb, true, now()),
  ('D10', 77, 'Discounts', 'Two offers on one item; blocking', 'Offer UAT-30PCT: Disc. Offer, 30%, same item as UAT-20PCT, Priority 2 (give UAT-20PCT Priority 1). Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring the item. Then tick Block Total Discount Offer on UAT-20PCT, publish, sync, and ring that item in a basket over 50.00 (D7).', 'Exactly one offer on the line: UAT-20PCT (lower Priority wins), never 30% and never 50%. With the block, the basket discount skips that line and still applies to the rest.', null, null, '[{"key":"which","label":"Offer applied / amount"},{"key":"blocked","label":"Basket discount on the blocked line / on the rest"}]'::jsonb, true, now()),
  ('D11', 78, 'Discounts', 'Offers that should not apply', 'Offers UAT-ENDED (Ending Date yesterday), UAT-LATER (Starting Date tomorrow) and UAT-OFF (Status Disabled), each a 50% Disc. Offer on one item. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring the three items.', 'All three at full price.', null, null, '[{"key":"ended","label":"UAT-ENDED item charged"},{"key":"later","label":"UAT-LATER item charged"},{"key":"off","label":"UAT-OFF item charged"}]'::jsonb, true, now()),
  ('D12', 79, 'Discounts', 'A price override beats the promotion', 'Ring the UAT-20PCT item. F11 Manager, 1 Price override, key a new price.', 'The keyed price stands and the promotion drops off that line; the till says a hand-keyed price is final. A cashier without Price Override needs a supervisor PIN, and the receipt shows who approved it.', null, null, '[{"key":"keyed","label":"Price keyed"},{"key":"charged","label":"Till charged"},{"key":"approver","label":"Approved by"}]'::jsonb, true, now()),
  ('D13', 80, 'Discounts', 'An item marked No Discount Allowed', 'On the UAT-20PCT item''s Item Card tick No Discount Allowed. Sync. Ring it; then F11 Manager, 2 Line discount, 10%.', 'No promotion on the line, and the line discount is refused with a reason.', null, 'Read in the code, not yet run: the till syncs No Discount Allowed but nothing reads it, so the offer and the manual discount both apply', '[{"key":"promo","label":"Promotion applied? amount"},{"key":"manual","label":"What the 10% did"}]'::jsonb, true, now()),
  ('D14', 81, 'Discounts', 'A coupon', 'Offer UAT-COUPON, Disc. Offer 15% on one item, Coupon Code UATCOUPON. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring the item and try to enter the coupon.', 'Without the coupon: full price. With it: 15% off.', null, 'Read in the code, not yet run: the till has no way to enter a coupon, so a coupon offer never applies', '[{"key":"how","label":"How you tried to enter it"},{"key":"charged","label":"Till charged"}]'::jsonb, true, now()),
  ('D15', 82, 'Discounts', 'Offer limits: price group and times applicable', 'Offer UAT-PG: Disc. Offer 25% on one item, Price Group = a group the walk-in customer is not in. Offer UAT-ONCE: Disc. Offer 25% on another item, No. of Times Applicable 1. Publish Rule Set (on the offer or the list), then F9 Status · Sync on the till. Ring the UAT-PG item with no customer; ring 3 of the UAT-ONCE item.', 'UAT-PG: full price. UAT-ONCE: 25% off one unit only.', null, 'Read in the code, not yet run: the till ignores an offer''s Price Group and No. of Times Applicable, so UAT-PG applies to everyone and UAT-ONCE to every unit', '[{"key":"pg","label":"UAT-PG item charged"},{"key":"once","label":"UAT-ONCE: discount on 3 units"}]'::jsonb, true, now()),
  ('D16', 83, 'Discounts', 'A promoted sale priced in ZWG', 'Ring the UAT-20PCT item and one ordinary item. Press F1 to price the sale in ZWG and read the confirm before you accept.', 'The confirm names UAT-20PCT as no longer applying in ZWG before anything changes; after it, the sale has no discount. (A blank Currency Code means the base currency; to run an offer in ZWG, make a copy with Currency Code ZWG.)', null, null, '[{"key":"confirm","label":"What the confirm said"},{"key":"usd","label":"Total before (USD)"},{"key":"zwg","label":"Total after (ZWG)"}]'::jsonb, true, now()),
  ('D17', 84, 'Discounts', 'Return a discounted item', 'Return one item from a D2 or D5 receipt.', 'The refund is what the customer paid for it, not the shelf price; the credit note shows the discount against the line.', null, null, '[{"key":"receipt","label":"Original receipt"},{"key":"paid","label":"Paid for the item"},{"key":"refunded","label":"Refunded"}]'::jsonb, true, now()),
  ('D18', 85, 'Discounts', 'Discounts on the Z', 'Cut the Z on a till that sold discounted items (T26).', 'The Z has a discounts section whose total equals the Promotions & discounts on that shift''s receipts.', null, null, '[{"key":"z","label":"Z no."},{"key":"z_total","label":"Discounts on the Z"},{"key":"receipts_total","label":"Sum from the receipts"}]'::jsonb, true, now()),
  ('D19', 86, 'Discounts', 'Discount entries in BC', 'Vantage Trans. Disc. Entries, filtered to the D receipts.', 'One entry per discount on each line, with the Discount Type (DISC_OFFER, MULTIBUY, MIX_MATCH, DEAL, TOTAL_DISCOUNT, LINE_DISCOUNT, MANUAL, TENDER_TYPE) and offer No., amounts matching the receipts.', null, null, '[{"key":"checked","label":"Receipts checked"},{"key":"mismatch","label":"Any mismatch"}]'::jsonb, true, now()),
  ('D20', 87, 'Discounts', 'Discounts post to their accounts', 'Calculate and post the statement for a day with D2 to D7 sales and no card discount (B4, B5). Look at the G/L entries.', 'Each kind of discount on its own account from D1; revenue plus discounts equals the shelf value; posted VAT equals the fiscal VAT; the statement''s Rounding Amount is cents at most.', null, null, '[{"key":"statement","label":"Statement no."},{"key":"discounts","label":"Amount per discount account"},{"key":"rounding","label":"Rounding Amount"}]'::jsonb, true, now()),
  ('D21', 88, 'Discounts', 'A card discount posts', 'Calculate and post the statement for the day of the D8 card sale.', 'It posts, with the card discount on Tender Disc. Account.', null, 'Read in the code, not yet run: a tender discount belongs to no sales line and posting only posts discounts that do, so the statement is out by the discount: it refuses to post above Max. Rounding Amount, otherwise the discount lands in the Rounding Account', '[{"key":"statement","label":"Statement no."},{"key":"result","label":"Posted, or the error"},{"key":"tender_acc","label":"Amount on Tender Disc. Account"},{"key":"rounding","label":"Rounding Amount"}]'::jsonb, true, now()),
  ('B1', 89, 'Business Central', 'Every transaction arrived', 'Count the transaction headers in BC for the shifts tested and compare with the till.', 'One per sale, none missing, voids present.', 'VPOS-31', null, '[{"key":"till_count","label":"Count on the till"},{"key":"bc_count","label":"Count in BC"},{"key":"missing","label":"Missing receipt nos."}]'::jsonb, true, now()),
  ('B2', 90, 'Business Central', 'Fiscal stamps on every header', 'Check the fiscal fields on each transaction header.', 'All present.', 'VPOS-31', null, '[{"key":"missing","label":"Headers without stamps"}]'::jsonb, true, now()),
  ('B3', 91, 'Business Central', 'Cash movements and the Z report arrived', 'Vantage Cash Movements and Vantage Z Reports for the shifts tested.', 'One Z per shift, with a ladder line per currency.', 'VPOS-33, VPOS-35', null, '[{"key":"z","label":"Z report no."},{"key":"currencies","label":"Currencies on the ladder"},{"key":"movements","label":"Cash movements found"}]'::jsonb, true, now()),
  ('B4', 92, 'Business Central', 'Calculate the statement', 'Create and calculate a statement for the store and date.', 'Each tender line in its own currency at the amount taken.', null, 'G1 (VPOS-90): a ZWG-notes tender reads the USD amount as ZWG', '[{"key":"statement","label":"Statement no."},{"key":"zwg_line","label":"ZWG tender line amount"}]'::jsonb, true, now()),
  ('B5', 93, 'Business Central', 'Post the statement', 'Post it.', 'It balances.', 'VPOS-35', null, '[{"key":"revenue","label":"Revenue"},{"key":"vat","label":"Output VAT"},{"key":"tenders","label":"Tenders"},{"key":"cash_diff","label":"Cash difference"}]'::jsonb, true, now()),
  ('B6', 94, 'Business Central', 'Drawer difference per currency', 'Vantage Statement Drawer for the statement.', 'One difference per drawer and currency, matching the Z.', 'VPOS-33', null, '[{"key":"usd","label":"USD difference"},{"key":"zwg","label":"ZWG difference"}]'::jsonb, true, now()),
  ('B7', 95, 'Business Central', 'Item ledger', 'Item Ledger Entries for the day''s sales.', 'Sale quantities posted.', 'VPOS-32', null, '[{"key":"entries","label":"Entries found"}]'::jsonb, true, now()),
  ('B8', 96, 'Business Central', 'Account sale invoice and oldest-first payment', 'Find the invoice for T21''s account sale. Pay part of the customer''s balance and check what it applied to.', 'The sale is its own invoice; the payment applies to the oldest entry first.', 'VPOS-56, VPOS-40', null, '[{"key":"invoice","label":"Invoice no."},{"key":"applied","label":"Entry the payment applied to"}]'::jsonb, true, now()),
  ('B9', 97, 'Business Central', 'Post the same day again', 'Try to post the day again.', 'Nothing moves.', null, null, '[{"key":"before","label":"G/L entries before"},{"key":"after","label":"G/L entries after"}]'::jsonb, true, now()),
  ('B10', 98, 'Business Central', 'Roll the statement back', 'Roll back the posted statement.', 'A net-zero reversal, and the transactions back to Open.', null, null, '[{"key":"doc","label":"Reversal document no."},{"key":"open","label":"Transactions back to Open? (yes/no)"}]'::jsonb, true, now())
